@pytest.fixture(scope="module")
def key_512():
    return generate_keypair(512)


def test_textbook_rsa():
    key = private_key_from_primes(61, 53, 17)
    assert (key.n, key.d) == (3233, 2753)
    assert encrypt_int(key.public_key, 65) == 2790
    assert decrypt_int(key, 2790) == 65


def test_private_key_matches_openssl_crt_parameters():
    key = private_key_from_primes(OPENSSL_KEY["p"], OPENSSL_KEY["q"])
    assert key.n == OPENSSL_KEY["n"]
    assert (key.dp, key.dq, key.q_inverse) == (
        OPENSSL_KEY["dp"],
        OPENSSL_KEY["dq"],
        OPENSSL_KEY["q_inverse"],
    )
    assert key.e * OPENSSL_KEY["d"] % math.lcm(key.p - 1, key.q - 1) == 1


def test_decrypts_openssl_pkcs1_ciphertext():
    key = private_key_from_primes(OPENSSL_KEY["p"], OPENSSL_KEY["q"])
    assert decrypt(key, OPENSSL_CIPHERTEXT) == OPENSSL_PLAINTEXT


def test_crt_matches_plain_exponentiation(key_512):
    for c in [0, 1, 2, key_512.n - 1, key_512.n // 3]:
        assert decrypt_int(key_512, c) == mod_pow(c, key_512.d, key_512.n)


def test_generated_key_is_valid(key_512):
    assert key_512.n.bit_length() == 512
    assert key_512.n == key_512.p * key_512.q
    assert key_512.p != key_512.q
    assert is_probable_prime(key_512.p) and is_probable_prime(key_512.q)
    assert key_512.e == PUBLIC_EXPONENT
    assert key_512.e * key_512.d % ((key_512.p - 1) * (key_512.q - 1)) == 1


def test_prime_window_returns_prime_with_top_bits_set():
    prime = find_prime_in_window(256) or find_prime_in_window(256)
    assert prime is not None
    assert prime.bit_length() == 256
    assert prime >> 254 == 0b11
    assert is_probable_prime(prime)
    assert (prime - 1) % PUBLIC_EXPONENT != 0


def test_small_odd_primes_sieve():
    primes = small_odd_primes()
    assert primes[:5] == (3, 5, 7, 11, 13)
    assert primes[-1] == 999983
    assert len(primes) == 78497


def test_sieve_window_marks_exactly_candidates_without_small_factors():
    start = (1 << 255) + 1
    survivors = sieve_window(start)
    primes = small_odd_primes()
    sample = list(range(0, SEARCH_WINDOW, 641)) + [SEARCH_WINDOW - 1]
    for index in sample:
        candidate = start + 2 * index
        assert survivors[index] == all(candidate % p for p in primes), index
    assert 0 < sum(survivors) < SEARCH_WINDOW // 5


def test_encrypted_block_follows_pkcs1_v1_5(key_512):
    k = modulus_bytes(key_512.n)
    ciphertext = encrypt(key_512.public_key, b"abc")
    assert len(ciphertext) == k
    encoded = decrypt_int(key_512, int.from_bytes(ciphertext, "big")).to_bytes(k, "big")
    padding = encoded[2 : k - 4]
    assert encoded[:2] == b"\x00\x02"
    assert len(padding) == k - 3 - 3 and 0 not in padding
    assert encoded[k - 4 :] == b"\x00abc"


def test_same_message_gives_different_ciphertexts(key_512):
    message = b"same text"
    assert encrypt(key_512.public_key, message) != encrypt(key_512.public_key, message)


@pytest.mark.parametrize("length", [0, 1, 53, 54, 55, 200])
def test_round_trip_any_length(key_512, length):
    message = bytes(i % 256 for i in range(length))
    ciphertext = encrypt(key_512.public_key, message)
    k = modulus_bytes(key_512.n)
    assert len(ciphertext) == k * max(1, -(-length // (k - 11)))
    assert decrypt(key_512, ciphertext) == message


def test_decrypt_rejects_bad_input(key_512):
    k = modulus_bytes(key_512.n)
    valid = encrypt(key_512.public_key, b"x")
    for bad in [b"", valid[:-1], valid + b"\x00", key_512.n.to_bytes(k, "big")]:
        with pytest.raises(ValueError):
            decrypt(key_512, bad)


@pytest.mark.parametrize(
    ("head", "padding_length", "separator"),
    [
        (b"\x00\x01", 8, True),
        (b"\x01\x02", 8, True),
        (b"\x00\x02", 7, True),
        (b"\x00\x02", 0, True),
        (b"\x00\x02", 62, False),
    ],
)
def test_decrypt_rejects_bad_padding(key_512, head, padding_length, separator):
    k = modulus_bytes(key_512.n)
    body = b"\xff" * padding_length + (b"\x00" if separator else b"")
    encoded = head + body + b"m" * (k - len(head) - len(body))
    assert len(encoded) == k
    ciphertext = encrypt_int(
        key_512.public_key, int.from_bytes(encoded, "big")
    ).to_bytes(k, "big")
    with pytest.raises(ValueError):
        decrypt(key_512, ciphertext)


def test_integer_operations_reject_out_of_range(key_512):
    with pytest.raises(ValueError):
        encrypt_int(key_512.public_key, key_512.n)
    with pytest.raises(ValueError):
        encrypt_int(key_512.public_key, -1)
    with pytest.raises(ValueError):
        decrypt_int(key_512, key_512.n)


def test_modulus_too_short_for_padding():
    with pytest.raises(ValueError):
        encrypt(PublicKey(3233, 17), b"")


@pytest.mark.parametrize("bits", [32, 63, 513])
def test_generate_keypair_rejects_bad_sizes(bits):
    with pytest.raises(ValueError):
        generate_keypair(bits)


def test_save_and_load_private_key(tmp_path, key_512):
    path = tmp_path / "key.json"
    save_private_key(key_512, str(path))
    assert load_private_key(str(path)) == key_512
    assert os.stat(path).st_mode & 0o777 == 0o600
    with pytest.raises(FileExistsError):
        save_private_key(key_512, str(path))


def test_public_key_view():
    key = PrivateKey(*range(1, 9))
    assert key.public_key == PublicKey(1, 2)
